def minPath(grid, k):
    from collections import deque
    import heapq

    n = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Priority queue: (lexicographical order, current position, path, current value)
    heap = []
    for i in range(n):
        for j in range(n):
            heapq.heappush(heap, (grid[i][j], (i, j), [grid[i][j]], grid[i][j]))

    visited = set()

    while heap:
        val, (x, y), path, current_val = heapq.heappop(heap)
        state = (x, y, len(path))
        if state in visited:
            continue
        visited.add(state)

        if len(path) == k:
            return path

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                new_path = path + [grid[nx][ny]]
                new_val = grid[nx][ny]
                heapq.heappush(heap, (new_val, (nx, ny), new_path, new_val))

